def transform(grid):
    h, w = len(grid), len(grid[0])
    all_colors = {x for row in grid for x in row}
    sep = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] not in {x for rr,row in enumerate(grid) if rr != r for x in row}:
            sep = ('row', r, grid[r][0]); break
    if sep is None:
        for c in range(w):
            color = grid[0][c]
            if all(grid[r][c] == color for r in range(h)) and color not in {grid[r][j] for r in range(h) for j in range(w) if j != c}:
                sep = ('col', c, color); break
    if sep is None:
        raise ValueError('separator not found')
    axis, k, _ = sep
    if axis == 'row':
        a, b = grid[:k], grid[k+1:]
        common = set(x for row in a for x in row) & set(x for row in b for x in row)
        color = next(iter(common))
        return [[3 if a[r][c] == color and b[r][c] == color else color for c in range(len(a[0]))] for r in range(len(a))]
    a = [row[:k] for row in grid]
    b = [row[k+1:] for row in grid]
    common = set(x for row in a for x in row) & set(x for row in b for x in row)
    color = next(iter(common))
    return [[3 if a[r][c] == color and b[r][c] == color else color for c in range(len(a[0]))] for r in range(h)]
